    long long n;
    cin >> n;
    vector<vector<string>> ops(n, vector<string>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> ops[i][j];
        }
    }

    vector<string> pages(n + 1);
    pages[0] = home;
    int cur = 0, end = 0;
    for (int i = 0; i < n; i++) {
        const string& op = ops[i][0];
        if (op == "visit") {
            cur++;
            pages[cur] = ops[i][1];
            end = cur;
        } else if (op == "back") {
