import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        String home = next();
        long n = Long.parseLong(next());
        String[][] ops = new String[(int) n][2];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = next();
            }
        }

        String[] pages = new String[(int) n + 1];
        pages[0] = home;
        int cur = 0, end = 0;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            String op = ops[i][0];
            if (op.equals("visit")) {
                cur++;
                pages[cur] = ops[i][1];
                end = cur;
            } else if (op.equals("back")) {
                cur = Math.max(0, cur - Integer.parseInt(ops[i][1]));
            } else {
                cur = Math.min(end, cur + Integer.parseInt(ops[i][1]));
            }
            sb.append(pages[cur]).append("\n");
        }
        System.out.print(sb);
    }
}
